package com.valor.configuration;
import com.valor.auth.AssetIdentityAccess; import com.valor.auth.Role; import com.valor.response.ApiResponse; import jakarta.validation.constraints.*; import java.util.*; import org.springframework.data.domain.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") class AssetConfigurationController {
 record Write(@NotBlank @Size(max=40) String category,@NotBlank @Size(max=80) String code,@NotBlank @Size(max=160) String label,@Size(max=500) String description,Boolean active,@Min(0) Integer displayOrder) {}
 record View(Long id,String category,String code,String label,String description,boolean active,int displayOrder,java.time.LocalDateTime createdAt,java.time.LocalDateTime updatedAt) {}
 private final ManagedAssetOptionRepository options; private final AssetIdentityAccess identities; AssetConfigurationController(ManagedAssetOptionRepository options,AssetIdentityAccess identities){this.options=options;this.identities=identities;}
 @GetMapping("/config/asset-options/{category}") ApiResponse<List<View>> active(@PathVariable String category){identities.actor(); return ApiResponse.success("Asset options",options.findByCategoryAndActiveTrueOrderByDisplayOrderAscIdAsc(normalize(category)).stream().map(AssetConfigurationController::view).toList(),200);}
 @GetMapping("/admin/config/asset-options") ApiResponse<Page<View>> list(@RequestParam String category,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){admin(); if(page<0||size<1||size>100)throw new IllegalArgumentException("Invalid page"); return ApiResponse.success("Asset options",options.findByCategoryOrderByDisplayOrderAscIdAsc(normalize(category),PageRequest.of(page,size)).map(AssetConfigurationController::view),200);}
 @PostMapping("/admin/config/asset-options") ApiResponse<View> create(@jakarta.validation.Valid @RequestBody Write input){admin(); String c=normalize(input.category()),code=input.code().trim().toUpperCase(Locale.ROOT); if(options.existsByCategoryAndCodeIgnoreCase(c,code))throw new IllegalArgumentException("Option code already exists"); ManagedAssetOption row=new ManagedAssetOption();row.category=c;row.code=code;apply(row,input);return ApiResponse.success("Asset option created",view(options.save(row)),201);}
 @PutMapping("/admin/config/asset-options/{id}") ApiResponse<View> update(@PathVariable Long id,@jakarta.validation.Valid @RequestBody Write input){admin(); ManagedAssetOption row=options.findById(id).orElseThrow(()->new IllegalArgumentException("Option not found"));String c=normalize(input.category()),code=input.code().trim().toUpperCase(Locale.ROOT);if(options.existsByCategoryAndCodeIgnoreCaseAndIdNot(c,code,id))throw new IllegalArgumentException("Option code already exists");row.category=c;row.code=code;apply(row,input);return ApiResponse.success("Asset option updated",view(options.save(row)),200);}
 @DeleteMapping("/admin/config/asset-options/{id}") ApiResponse<View> deactivate(@PathVariable Long id){admin(); ManagedAssetOption row=options.findById(id).orElseThrow(()->new IllegalArgumentException("Option not found"));row.active=false;return ApiResponse.success("Asset option deactivated",view(options.save(row)),200);}
 private void apply(ManagedAssetOption row,Write i){row.label=i.label().trim();row.description=i.description()==null?null:i.description().trim();row.active=i.active()==null||i.active();row.displayOrder=i.displayOrder()==null?0:i.displayOrder();}
 private void admin(){Role role=identities.actor().getRole();if(role!=Role.ADMIN&&role!=Role.SUPER_ADMIN)throw new org.springframework.security.access.AccessDeniedException("Access denied");} private static String normalize(String value){String v=value==null?"":value.trim().toUpperCase(Locale.ROOT);if(!Set.of("BUILDING_TYPE","BUILDING_PREFERENCE","LIFT_TYPE","DOOR_OPERATION","DOOR_DESIGN").contains(v))throw new IllegalArgumentException("Unsupported option category");return v;} private static View view(ManagedAssetOption r){return new View(r.id,r.category,r.code,r.label,r.description,r.active,r.displayOrder,r.createdAt,r.updatedAt);}
}
